      title = "Falmonius \\#1: This Can't Be Good!",
      exp = "19",
      exp_name = "Rain of Fear",
      min_lvl = 1,
      max_lvl = 125,
      quest_type = "",
      repeatable = false,
      group_size = "",
      npc = "Hurble",
      loc = { y = 500.0, x = -1715.0, z = 145.0 },
      triggers = {
        "Hail, Hurble",
        "What help?",
